challenge.solution:
def home():
    return "<h1>Ana sayfa</h1>"

def about():
    return "<h1>Hakkında</h1>"

routes = {"/": home, "/hakkinda": about}

def handle(path):
    if path in routes:
        return (200, routes[path]())
    return (404, "<h1>Bulunamadı</h1>")

print(handle("/"))
print(handle("/gizli"))

