def render_todo(tasks):
    html = "<h1>Yapılacaklar</h1><ul>"
    for title, done in tasks:
        if done:
            html += f"<li><s>{title}</s></li>"
        else:
            html += f"<li>{title}</li>"
    html += "</ul>"
    return html


print(render_todo([("Kahve", True), ("Spor", False)]))

